ICChoice = "green"; %[control:dropdown:56db]{"position":[12,19]}
%[text] These values should be numbers:
tStar = 0; %[control:editfield:2d7d]{"position":[9,10]}
xStar = -1; %[control:editfield:91ab]{"position":[9,11]}
%[text] Identify the equations that bound the rarefaction region. These values should be functions of $t${"altText":"t"}.
xPlus =  jumppoint+t*speed; %[control:editfield:7407]{"position":[9,27]}
xMinus = jumppoint; %[control:editfield:0ce8]{"position":[10,19]}
  %[control:button:2fb3]{"position":[1,2]}
CheckExercise2(ICChoice,tStar,xStar,xPlus,xMinus,jumppoint,abs(speed)) %[output:79844b2f] %[output:422628ac] %[output:53344eb6] %[output:9a787efb] %[output:52fd7e38]
