    tVals = linspace(t0,3,100);
    xVals = -10:0.2:10;
    xLimitValues = [-4 6];
    [xShock,uPlus,uMinus] = SolveShock(tShockVals,tShockIdx,xStar,yPlus,yMinus,ICf,T=u,X=1/2*u^2);
    ax = PlotCharacteristicCurves(tVals,xVals,ICf,xEqnShock,xLimitValues, ... %[output:1c8f2a95]
        DrawShock=true,ShockTimes=tShockVals,ShockVals=xShock); %[output:1c8f2a95]
    hold on %[output:1c8f2a95]
    plot(ax,tShockVals,xShock,LineWidth=3,SeriesIndex="none") %[output:1c8f2a95]
    hold off %[output:1c8f2a95]
else
    disp("You must complete Exercise 3 before plotting the result.")
end %[output:group:910011f9]
%[text] Therefore, the solutions look like:
if exist("PassedEx3","var") && PassedEx3 %[output:group:1e1fa373]
