    [xShock,uPlus,uMinus] = SolveShock(tShockVals,tShockIdx,xStar,yPlus,yMinus,ICf,t0Idx,T=u,X=1/2*u^2);

    ax = PlotCharacteristicCurves(tVals,xVals,ICf,xEqnShock,xLimitValues, ... %[output:056d3a29]
        DrawShock=true,ShockTimes=tShockVals,ShockVals=xShock); %[output:056d3a29]
    hold on %[output:056d3a29]
